var CONV_T = window.CONV_T || {}; CONV_T["pl"] = {"twoOverOne":["2/1 forsujące do końcówki","Z ręki niespasowanej nowy kolor na poziomie dwóch po otwarciu partnera na poziomie jednego (poza 1♣–2♦; 1♠–2♥ pokazuje pięć kierów) forsuje do końcówki, 12+ PC. Na 1♥/1♠ odpowiedź 1BA jest forsująca na jedno okrążenie (6-12 PC): otwierający bez innej odzywki powtarza trzykartowy młodszy; późniejszy skok odpowiadającego na 3 w starszym pokazuje inwitujące poparcie z trzema kartami. Odpowiedź na poziomie dwóch z ręki spasowanej nie forsuje."],"rkc":["RKCB 1430","4BA pyta o pięć kart kluczowych (cztery asy + król atutowy). 5♣ = 1 lub 4, 5♦ = 3 lub 0, 5♥ = 2 bez damy atutowej, 5♠ = 2 z damą atutową."],"rkc0314":["RKCB 0314","4BA pyta o pięć kart kluczowych (cztery asy + król atutowy). 5♣ = 0 lub 3, 5♦ = 1 lub 4, 5♥ = 2 bez damy atutowej, 5♠ = 2 z damą atutową. Zamiast RKCB 1430."],"gerber":["Gerber","Po 1BA, 2BA lub 3BA partnera, bez uzgodnionego koloru, 4♣ pyta o asy. 4♦ = 0 lub 4, 4♥ = 1, 4♠ = 2, 4BA = 3. Pytający może zatrzymać się na 4BA."],"bergen":["Podniesienia Bergena","Na 1♥/1♠ (nie po kontrze ani wejściu): 3♣ = poparcie czterokartowe, 7-9 punktów; 3♦ = cztery karty, 10-12 (inwit); 3 w starszym = cztery karty, 0-6 (blok). Z czterema kartami i 13+ używa się Jacoby 2BA lub splintra. Proste podniesienie pokazuje trzy karty, 6-9; inwit z trzema kartami idzie przez forsujące 1BA."],"capp":["Cappelletti","Na 1BA przeciwników (na pozycji bezpośredniej): X = karna, 15+ PC. 2♣ = jednokolorówka (6+ kart): partner pyta 2♦, wchodzący pasuje z karami lub nazywa kolor. 2♦ = oba starsze (5-4 lub dłużej): partner wybiera starszy (skok jest inwitem, 10-12). 2♥/2♠ = 5+ w tym starszym i młodszy 4+: partner pasuje, podnosi lub pyta o młodszy przez 2BA. 2BA = oba młodsze (5-5): partner wybiera."],"j2nt":["Jacoby 2BA","2BA na otwarcie w starszym = poparcie 4+ kart, 13+ punktów, forsuje do końcówki. Otwierający: 3 w nowym kolorze = singel lub renons; 4 w nowym kolorze = dobra boczna piątka; 3 w starszym = 18+ bez krótkości; 3BA = 15-17 bez krótkości; 4 w starszym = minimum."],"wjs":["Słabe skoki","Pojedynczy skok odpowiadającego w nowym kolorze (np. 1♦–2♠, 1♣–2♥) pokazuje kolor 6+ i słabą rękę (0-5 PC). To do gry; otwierający pasuje. Nie po kontrze przeciwnika."],"stayman":["Stayman","2♣ po 1BA (3♣ po 2BA) pyta o czwórkę w starszym. Odpowiedzi: ♦ = brak czwórki w starszym, ♥ = cztery kiery, ♠ = cztery piki i nie cztery kiery. Po 2♦ 2♥/2♠ = pięć w tym starszym + cztery w drugim, inwit. Jeśli odpowiadający licytuje BA na 2♥, otwierający z czterema pikami też je zgłasza."],"minorTr":["Transfer na młodszy","Po 1BA: 2♠ → trefle (otwierający licytuje 3♣), 3♣ → kara (otwierający licytuje 3♦). Słaba ręka z szóstką w młodszym gra na trzech; 2BA pozostaje naturalną inwitą."],"fourWay":["Transfery czterokierunkowe","Po 1BA: 2♦ → kiery, 2♥ → piki (Jacoby), 2♠ → trefle (otwierający mówi 3♣), 2BA → kara (otwierający mówi 3♦). Równe inwity idą przez 2♣ Stayman."],"puppet":["Puppet Stayman","Po 2BA 3♣ pyta o starszy kolor 4- lub 5-kartowy (zamiast Staymana). Odpowiedzi: 3♦ = jeden lub dwa starsze czwórki, 3♥ = pięć kierów, 3♠ = pięć pików, 3BA = brak starszej czwórki. Po 3♦ odpowiadający licytuje starszy, którego nie ma: 3♥ = cztery piki, 3♠ = cztery kiery, 4♦ = oba, 3BA = żadnego; dzięki temu rozgrywa otwierający 2BA."],"smolen":["Smolen","Po 1BA–2♣–2♦ ręka forsująca do końcówki z układem 5-4 w starszych zgłasza czwórkę w starszym na poziomie trzech: 3♥ = 4♥ + 5♠, 3♠ = 4♠ + 5♥, aby rozgrywała silna ręka."],"michaels":["Cue bid Michaelsa / nietypowe 2BA","Bezpośredni cue bid ich otwarcia na poziomie jednego pokazuje dwukolorówkę 5-5, 7+ PC: na młodszy — oba starsze; na starszy — drugi starszy i młodszy (partner pyta o młodszy przez 2BA). Skok na 2BA (nietypowe) pokazuje dwa najniższe niezalicytowane kolory. Partner wybiera; z fitem i 10+ może skoczyć do końcówki."],"splinter":["Splinter","Podwójny skok w nowym kolorze na otwarcie w starszym (np. 1♠–4♥, 1♥–3♠) = poparcie 4+ kart, singel lub renons w nazwanym kolorze, 11-15 PC, forsuje do końcówki, zainteresowanie szlemem. Otwierający zatrzymuje się na 4 w starszym lub bada szlema."],"texas":["Teksas","Po 1BA/2BA: 4♦ → 4♥, 4♥ → 4♠. Starszy 6+ z siłą na końcówkę; rozgrywa silna ręka (otwierający)."],"texasInt":["Teksas po interwencji","Teksas obowiązuje, gdy przeciwnicy kontrują nasze 1BA lub wchodzą na poziomie dwóch-trzech: 4♦ → kiery, 4♥ → piki. Odzywka w ich kolorze nie jest transferem (po wejściu 2♥ 4♥ to cue bid, a 4♦ nadal pokazuje kiery). Otwierający kończy transfer."],"leb":["Lebensohl","Po wejściu na poziomie dwóch w nasze 1BA: 2BA zmusza otwierającego do 3♣ (aby zatrzymać się w kolorze lub pokazać powoli). Bezpośredni kolor na poziomie trzech forsuje. Bezpośrednie 3BA zaprzecza zatrzymaniu; 2BA, a potem 3BA je pokazuje. Cue bid ich koloru to Stayman: bezpośrednio = bez zatrzymania, przez 2BA = z zatrzymaniem („szybko zaprzecza”)."],"lav":["Zrzutki Lavinthala","Sygnalizacja w obronie. Zrzucony kolor jest niechciany; wysoka karta prosi o wyższy z dwóch pozostałych kolorów, niska o niższy (atut i kolor wiodący się nie liczą). Na wist partnera wysoka karta zachęca, najniższa zniechęca."],"roman":["Zrzutki rzymskie (parzyste-nieparzyste)","Sygnalizacja w obronie. Pierwsza zrzutka: karta nieparzysta (3, 5, 7, 9) prosi o ten kolor; parzysta (2, 4, 6, 8, 10) go nie chce i prosi o jeden z dwóch pozostałych kolorów: niska parzysta (2, 4) o niższy, wysoka (6, 8, 10) o wyższy (atut i kolor zagrany się nie liczą). Na wist partnera wysoka blotka zachęca, najniższa zniechęca."],"invMin":["Odwrócone podniesienia młodszych","Z ręki niespasowanej na 1♣/1♦: podniesienie do 2 w młodszym jest silne (10+ punktów, 4+ poparcia, 5+ w treflach, bez czwórki w starszym) i forsuje na jedno okrążenie; otwierający z równym minimum mówi 2BA, z nadwyżką pokazuje zatrzymania, z minimum powtarza 3 w młodszym. Skokowe podniesienie do 3 to blok (0-9 punktów, 5+ poparcia)."],"drury":["Drury","Odwrócone Drury. Ręka spasowana odpowiada na 1♥/1♠ partnera z trzeciej/czwartej ręki 2♣ = poparcie 3+ kart i 10-12 punktów. Otwierający z lekkim lub minimalnym otwarciem powtarza 2 w starszym (bez końcówki), z pełnym mówi 4 w starszym."],"nmf":["Nowy młodszy forsujący","Po 1m–1M–1BA 2 w drugim młodszym u odpowiadającego jest sztuczne i forsujące (11+): pyta otwierającego o trzykartowe poparcie starszego odpowiadającego lub o drugą czwórkę w starszym."],"fsf":["Czwarty kolor forsujący","Gdy nasza strona zgłosiła trzy kolory, odzywka odpowiadającego w czwartym kolorze jest sztuczna i forsuje do końcówki; prosi otwierającego o dalszy opis (zatrzymanie, poparcie lub dodatkowa długość)."],"ogust":["Ogust","Po słabym dwa partnera 2BA pyta: 3♣ = minimum, słaby kolor; 3♦ = minimum, dobry kolor; 3♥ = maksimum, słaby kolor; 3♠ = maksimum, dobry kolor; 3BA = kolor zamknięty (AKD)."],"supx":["Kontra poparcia","Po 1m–(pas)–1M–(wejście poniżej 2M) kontra otwierającego pokazuje dokładnie trzy karty poparcia w starszym odpowiadającego; bezpośrednie podniesienie pokazuje cztery."],"respx":["Kontra responsywna","Po ich otwarciu, wywoławczej kontrze partnera i ich podniesieniu kontra partnera kontrującego jest wywoławcza: 8+ punktów i oba niezalicytowane kolory (zwykle starsze), bez jasnej odzywki."],"sjs":["Silne skoki","Pojedynczy skok odpowiadającego w nowym kolorze pokazuje silną rękę (19+ punktów) z dobrym kolorem i zainteresowaniem szlemem. Zastępuje słabe skoki."],"dont":["DONT","Disturb Opponents’ Notrump (Marty Bergen). Na ich 1BA: X = jednokolorówka (6+), partner pyta 2♣; 2♣ = trefle i wyższy kolor; 2♦ = kara i starszy; 2♥ = oba starsze; 2♠ = tylko piki (naturalnie). Partner pasuje z tolerancją lub mówi następny kolor (pas lub popraw). Zastępuje Cappelletti."],"jtr":["Transfer Jacoby","Po 1BA 2♦ prosi otwierającego o kiery, a 2♥ o piki, aby rozgrywała silna ręka. Z czterokartowym poparciem i maksimum (17) otwierający superakceptuje na poziomie trzech. Po transferze nowy kolor na poziomie trzech jest naturalny i forsuje do końcówki."],"sys":["Odzywka systemowa","Sztuczna odzywka wybranego systemu (Precision, Wspólny Język, Multi 2♦): co pokazuje, napisano powyżej. System wybiera się na stronie głównej (Twój system) lub w Ustawieniach."],"bw":["Blackwood","4BA pyta o asy: 5♣ = 0 lub 4, 5♦ = 1, 5♥ = 2, 5♠ = 3."],"q":["Ilościowe 4BA","Po odzywce bez atu 4BA nie pyta o asy, tylko zaprasza do szlema. Partner z maksimum mówi 6BA."],"nego":["Kontra negatywna","Gdy partner otworzył, a przeciwnik wszedł, kontra nie jest karna: pokazuje cztery karty w niezalicytowanym starszym i siłę do licytacji."],"takeout":["Kontra wywoławcza","Kontra otwarcia: siła otwarcia, krótkość w ich kolorze i poparcie w pozostałych kolorach. Partner musi licytować."],"weak2":["Słabe dwa","Otwarcie 2♦/2♥/2♠: dobra szóstka, 5-10 PC. Otwarcie blokujące."],"strong2c":["Silne 2♣","Otwarcie 2♣: 22+ PC lub równoważna siła lewowa, sztuczne i forsujące do końcówki. 2♦ to odpowiedź wyczekująca. Po 2♣–2♦–2♥/2♠ 3♣ to drugi negatyw (0-3 PC); 2♣–2♦–2BA (22-24) licytuje się jak otwarcie 2BA (Stayman i transfery)."],"cue":["Cue bid","Odzywka w kolorze przeciwników nie jest naturalna: pokazuje poparcie dla partnera z inwitem lub więcej i forsuje."],"nt1":["Otwarcie 1BA","15-17 PC, układ zrównoważony."],"pre":["Blok","Otwarcie na poziomie trzech lub czterech: długi kolor (7+) i słaba ręka, zabiera przeciwnikom przestrzeń licytacyjną."],"runout":["Ucieczka po skontrowanym 1BA","Gdy nasze 1BA zostanie skontrowane, słaby odpowiadający ucieka w kolor 5+; rekontra pokazuje siłę (9+)."]};
var SYS_T = window.SYS_T || {}; SYS_T["pl"] = {"twoone":"Piątki w starszych, 1BA 15-17, słabe dwa, silne 2♣. Nowy kolor na poziomie dwóch u niespasowanego odpowiadającego forsuje do końcówki; 1BA na starszy forsuje.","sayc":"Piątki w starszych, 1BA 15-17, słabe dwa, silne 2♣, transfery Jacoby i Stayman, Blackwood. Nowy kolor na poziomie dwóch forsuje na okrążenie (10+); 1BA na starszy to 6-10 i nie forsuje; skoki są silne.","acol":"Czwórki w starszych, słabe 1BA (12-14), silne 2♣ (23+ lub do końcówki), słabe dwa w ♦ ♥ ♠, podniesienia limitowe (podniesienie obiecuje cztery karty), 2BA 20-22, Stayman i transfery, RKCB.","sef":"Système d’Enseignement Français: piątki w starszych, „lepszy młodszy” 1♣/1♦, 1BA 15-17, silne i forsujące 2♣, sztuczne 2♦ forsujące do końcówki, słabe 2♥/2♠. Nowy kolor na poziomie dwóch forsuje na okrążenie; RKCB.","precision":"Silny trefl: 1♣ = 16+ dowolny układ (sztuczne, forsujące; 1♦ = negatyw 0-7). Inne otwarcia 11-15: 1♦ 2+ ♦ (zbiorcze), 1♥/1♠ 5+, 1BA 13-15, 2♣ 6+ ♣ (lub 5♣ + czwórka w starszym), 2♦ trójkolorówka krótka w ♦ (4-4-1-4 / 4-4-0-5), słabe 2♥/2♠.","polish":"Wspólny Język: 1♣ = (a) 12-14 zrównoważone, (b) 15+ z długimi treflami lub (c) 18+ dowolne (1♦ = negatyw 0-7 lub odpowiedź wyczekująca). 1♦ 4+ ♦ niezrównoważone, 1♥/1♠ 5+, 1BA 15-17, 2♣ 6+ ♣ 11-15, 2♦ Multi (słabe dwa w ♥ lub ♠), słabe 2♥/2♠."};
